submit_catalog_item.beforeRequest:
if (!(inputs.item_sys_id || inputs.manual_item_sys_id)) throw new Error('Either catalog item selection or manual sys_id must be provided');
var quantity = inputs.quantity === undefined || inputs.quantity === '' ? 1 : Number(inputs.quantity);
if (!Number.isInteger(quantity) || quantity < 1 || quantity > 100) throw new Error('Quantity should be a whole number from 1 to 100');
request.url = request.url.replace(/ITEM/, encodeURIComponent(inputs.item_sys_id || inputs.manual_item_sys_id));
request.body.sysparm_quantity = String(quantity);
var variables = inputs.variables ? JSON.parse(inputs.variables) : null;
if (variables !== null && (typeof variables !== 'object' || Array.isArray(variables))) throw new Error('Variables should be a JSON object');
if (variables && Object.keys(variables).length > 0) request.body.variables = variables;
return request;

search_knowledge_articles.beforeRequest:
