if (!Number.isInteger(offset) || offset < 0) throw new Error('Offset should be a whole number of 0 or more');
request.query.sysparm_limit = String(limit);
request.query.sysparm_offset = String(offset);
var fields = inputs.fields ? JSON.parse(inputs.fields) : [];
if (fields.length > 0) request.query.fields = fields.join(',');
return request;

search_knowledge_articles.afterResponse:
if (!response || typeof response.result !== 'object' || response.result === null) throw new Error('The answer has no result');
