send_email.beforeRequest:
var email = /^(?!\.)(?!.*\.\.)([A-Za-z0-9_'+\-\.]*)[A-Za-z0-9_+-]@([A-Za-z0-9][A-Za-z0-9\-]*\.)+[A-Za-z]{2,}$/;
function check(address) { if (typeof address !== 'string' || !email.test(address)) throw new Error('Invalid email address: ' + address); }
if (inputs.from) check(inputs.from);
['to', 'cc', 'bcc'].forEach(function (name) {
  var list = inputs[name] ? JSON.parse(inputs[name]) : [];
  list.forEach(check);
  if (name === 'to' && list.length === 0) throw new Error('At least one recipient is required');
  if (list.length > 0) request.body[name] = list.join(',');
});
return request;

